<?php
declare(strict_types=1);

/**
 * Settings for the accounts/items API. Lookup order: environment variable `QR_<KEY>` → PHP constant `<KEY>`
 * (config.local.php locally, config.php generated by the deploy workflow in production) → default below.
 * Secrets never go into the repository. All keys are listed in docs/ACCOUNTS.md.
 */
final class Config
{
    private const DEFAULTS = [
        // Long random string (>= 32 chars): hashes login codes and IP addresses. openssl rand -hex 32
        'AUTH_SECRET' => '',
        // This site (links in login mails sent from the landing page) and the viewer (links from the viewer)
        'QR_URL' => 'https://qr.scutoons.com',
        'APP_URL' => 'https://scutoons.com',
        // Item icons: <CDN_URL><icon path>. Local CDN: http://localhost:8001/
        'CDN_URL' => 'https://cdn.scutoons.com/',
        // Browser origins that may call the API with credentials (comma separated) – ITEMS.md
        'ALLOWED_ORIGINS' => 'https://scutoons.com,https://www.scutoons.com,http://localhost:5173,http://localhost:5174,http://localhost:5175,http://localhost:4173',
        // smtp (production) | log (development: mails appended to MAIL_LOG_PATH) | mail (PHP mail())
        'MAIL_TRANSPORT' => 'smtp',
        'MAIL_FROM' => 'no-reply@scutoons.com',
        'MAIL_FROM_NAME' => 'SCUTOONS',
        'MAIL_LOG_PATH' => __DIR__ . '/../../logs/mail.log',
        'SMTP_HOST' => '',
        'SMTP_PORT' => '587',
        // tls = STARTTLS (587), ssl = implicit TLS (465), none = plain (local test servers only)
        'SMTP_SECURE' => 'tls',
        'SMTP_USER' => '',
        'SMTP_PASS' => '',
        'SMTP_TIMEOUT' => '15',
        // Login limits
        // POST /auth/code/ attempts per IP and hour (every attempt counts)
        'AUTH_CODE_MAX_PER_IP_HOUR' => '60',
        // Another permissions map (default api/permissions.json)
        'PERMISSIONS_PATH' => '',
        'LOGIN_TTL_MINUTES' => '30',
        'LOGIN_MAX_ATTEMPTS' => '5',
        'LOGIN_MAX_PER_EMAIL_HOUR' => '5',
        'LOGIN_MAX_PER_IP_HOUR' => '30',
        'SESSION_TTL_DAYS' => '365',
        // Inventory limits
        'GRANT_MAX_PER_HOUR' => '120',
        'IMPORT_MAX_PER_HOUR' => '10',
        'IMPORT_MAX_QTY' => '99',
        'PROGRESS_MAX_BYTES' => '262144',
        // API error log (logs/ is never served); empty = the host's log
        'LOG_PATH' => __DIR__ . '/../../logs/error.log',
    ];

    public static function get(string $key): string
    {
        $env = getenv('QR_' . $key);
        if ($env !== false && $env !== '') return $env;
        // An empty constant (e.g. an unset CI variable) falls back to the default
        if (defined($key) && (string) constant($key) !== '') return (string) constant($key);
        return self::DEFAULTS[$key] ?? '';
    }

    public static function int(string $key): int
    {
        return (int) self::get($key);
    }

    /** @return string[] */
    public static function list(string $key): array
    {
        return array_values(array_filter(array_map('trim', explode(',', self::get($key)))));
    }
}
